using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using KoreanAIR;
using System.IO.Compression;
using System.Runtime.InteropServices;

public static class FrameGenerationAudit {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool DeleteFile(string path);
 static List<string> checks=new List<string>();static string fixture,destination;
 static void Check(bool passed,string name){if(!passed)throw new Exception(name);checks.Add(name);}
 static void Fails(Action action,string name){bool failed=false;try{action();}catch{failed=true;}Check(failed,name);}
 static Control Find(Control parent,string name){if(parent.Name==name)return parent;foreach(Control c in parent.Controls){var hit=Find(c,name);if(hit!=null)return hit;}return null;}
 static string Engine{get{return Path.Combine(Core.FrameGenerationTestDirectory,"Engine.ini");}}
 static string New(string name,byte[] bytes=null,bool readOnly=false){
  string root=Path.Combine(fixture,name);Directory.CreateDirectory(root);Core.FrameGenerationTestDirectory=Path.Combine(root,"config");Directory.CreateDirectory(Core.FrameGenerationTestDirectory);
  if(bytes!=null){File.WriteAllBytes(Engine,bytes);if(readOnly)File.SetAttributes(Engine,FileAttributes.ReadOnly);}
  var state=new State{root=root,mouse=true,build=Core.ReleaseBuild,backup=Path.Combine(root,"backup")};Core.Text(Core.Safe(root,Core.Folder+"/installed.json"),Core.Json.Serialize(state));return root;
 }
 static byte[] Encode(string text,string encoding){return encoding=="utf16le"?Encoding.Unicode.GetPreamble().Concat(Encoding.Unicode.GetBytes(text)).ToArray():encoding=="utf16be"?Encoding.BigEndianUnicode.GetPreamble().Concat(Encoding.BigEndianUnicode.GetBytes(text)).ToArray():encoding=="utf8bom"?new byte[]{239,187,191}.Concat(Encoding.UTF8.GetBytes(text)).ToArray():Encoding.UTF8.GetBytes(text);}
 static void External(string text){if(File.Exists(Engine))File.SetAttributes(Engine,FileAttributes.Normal);File.WriteAllText(Engine,text,new UTF8Encoding(false));File.SetAttributes(Engine,FileAttributes.ReadOnly);}
 static void Capture(Form form,string name){Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(destination,name+".png"));}}
 static void GameFixture(string root){
  string exe=Core.Safe(root,"Game/Binaries/Win64/AceCombat8.exe");Directory.CreateDirectory(Path.GetDirectoryName(exe));byte[] bytes=new byte[256];using(var stream=new MemoryStream(bytes))using(var writer=new BinaryWriter(stream)){writer.Write((ushort)0x5a4d);stream.Position=0x3c;writer.Write(64);stream.Position=64;writer.Write((uint)0x4550);writer.Write((ushort)0x8664);stream.Position=72;writer.Write((uint)0x6aa0e27d);stream.Position=144;writer.Write((uint)0x2195a000);}File.WriteAllBytes(exe,bytes);Core.Text(Core.Safe(root,"start_protected_game.exe"),"fixture");Core.Text(Core.Safe(root,"EasyAntiCheat/Settings.json"),"{\"executable\":\"Game/Binaries/Win64/AceCombat8.exe\"}");
 }
 static MemoryStream Payload(){
  var stream=new MemoryStream();var files=new List<Item>();var payload=new Dictionary<string,byte[]>{{Core.Mod+"config.ini",Encoding.UTF8.GetBytes("[control]\nsensitivity=0.03\n")},{"Game/Binaries/Win64/dwmapi.dll",Encoding.UTF8.GetBytes("synthetic loader")},{"KoreanAIR_AC8_ModPack/README_ENG.txt",Encoding.UTF8.GetBytes("fixture README")}};
  using(var zip=new ZipArchive(stream,ZipArchiveMode.Create,true)){foreach(var pair in payload){string source="payload/"+pair.Key;files.Add(new Item{path=pair.Key,source=source,hash=Core.Hash(pair.Value),group=pair.Key.StartsWith(Core.Folder)?"common":"runtime",mutable=pair.Key.EndsWith(".ini")});using(var entry=zip.CreateEntry(source).Open())entry.Write(pair.Value,0,pair.Value.Length);}byte[] manifest=Encoding.UTF8.GetBytes(Core.Json.Serialize(new Manifest{files=files,legacy=new Dictionary<string,string>()}));using(var entry=zip.CreateEntry("manifest.json").Open())entry.Write(manifest,0,manifest.Length);}stream.Position=0;return stream;
 }
 static void CoreCases(){
  string root=New("default");Check(Core.FrameGenerationRequested(root)==null&&!File.Exists(Engine),"new installation never forces FG on");
  string gus=Path.Combine(Core.FrameGenerationTestDirectory,"GameUserSettings.ini");byte[] manual=Encode("[ConsoleVariables]\r\nr.Streamline.DLSSG.Enable=1\r\nt.Streamline.Reflex.Mode=2\r\n","utf8");File.WriteAllBytes(gus,manual);
  Check(Core.FrameGenerationRequested(root)==true,"manual GameUserSettings FG intent inherited");Core.SetFrameGeneration(root,false);Check(Core.FrameGenerationRequested(root)==false&&File.ReadAllBytes(gus).SequenceEqual(manual),"explicit off overrides manual intent while preserving GUS bytes");Core.RestoreFrameGeneration(root);Check(!File.Exists(Engine)&&Core.FrameGenerationRequested(root)==true,"restore removes new Engine file and returns original manual request");
  foreach(string encoding in new[]{"utf8","utf8bom","utf16le","utf16be"})foreach(bool readonlyFlag in new[]{false,true}){
   byte[] original=Encode("; 외부 설정\r\n[ConsoleVariables]\r\nr.Streamline.DLSSG.Enable=0\r\nr.Foreign=73\r\n[/Script/Engine.RendererSettings]\r\nr.Other=9",encoding);
   root=New(encoding+readonlyFlag,original,readonlyFlag);Core.SetFrameGeneration(root,true);
   Check(File.ReadAllBytes(Engine).Take(original.Length).SequenceEqual(original),encoding+" external bytes preserved");Check(Core.ReadState(root).frameGeneration.enabled&&Core.FrameGenerationRequested(root)==true,encoding+" on lease saved");
   Check((File.GetAttributes(Engine)&FileAttributes.ReadOnly)!=0,encoding+" live override protected from game deletion");Check(!DeleteFile(Engine)&&Marshal.GetLastWin32Error()==5&&File.Exists(Engine),encoding+" native DeleteFile refuses live protected configuration");
   Core.SetFrameGeneration(root,false);Check(Core.FrameGenerationRequested(root)==false,encoding+" off lease saved");Core.Suspend(root,true);Check(File.ReadAllBytes(Engine).SequenceEqual(original),encoding+" suspend restores original bytes");Check(((File.GetAttributes(Engine)&FileAttributes.ReadOnly)!=0)==readonlyFlag,encoding+" suspend restores original ReadOnly");
   Fails(()=>Core.SetFrameGeneration(root,true),encoding+" save while suspended rejected");Core.Suspend(root,false);Check(Core.FrameGenerationRequested(root)==false,encoding+" resume preserves selected off");Core.RestoreFrameGeneration(root);Check(File.ReadAllBytes(Engine).SequenceEqual(original),encoding+" restore returns exact bytes");Check(((File.GetAttributes(Engine)&FileAttributes.ReadOnly)!=0)==readonlyFlag,encoding+" restore returns exact ReadOnly");
  }
  root=New("external_changes",Encode("[User]\nkey=7\n","utf8"));Core.SetFrameGeneration(root,true);External(File.ReadAllText(Engine)+"other=8\n");Core.RestoreFrameGeneration(root);Check(File.ReadAllText(Engine)=="[User]\nkey=7\nother=8\n","external changes outside owned block survive restore");
  root=New("tampered");Core.SetFrameGeneration(root,true);External(File.ReadAllText(Engine).Replace("r.Streamline.DLSSG.Enable=1","r.Streamline.DLSSG.Enable=0"));byte[] tampered=File.ReadAllBytes(Engine),state=File.ReadAllBytes(Core.Safe(root,Core.Folder+"/installed.json"));
  Fails(()=>Core.SetFrameGeneration(root,false),"edited owned block prevents setting overwrite");Fails(()=>Core.RestoreFrameGeneration(root),"edited owned block prevents restore");Fails(()=>Core.Suspend(root,true),"edited owned block prevents suspend");Fails(()=>Core.Uninstall(root),"edited owned block prevents uninstall");Check(File.ReadAllBytes(Engine).SequenceEqual(tampered)&&File.ReadAllBytes(Core.Safe(root,Core.Folder+"/installed.json")).SequenceEqual(state),"tamper refusal preserves file and installation record");
  root=New("duplicate",Encode("[ConsoleVariables]\nr.Streamline.DLSSG.Enable=9\n","utf8"));Fails(()=>Core.SetFrameGeneration(root,true),"invalid existing managed-key value fails closed");
  root=New("invalid_encoding",new byte[]{0xff,0x00,0xf8});Fails(()=>Core.SetFrameGeneration(root,true),"invalid encoding fails closed");
  root=New("ownership_a");Core.SetFrameGeneration(root,true);string other=Path.Combine(fixture,"ownership_b");Directory.CreateDirectory(other);Core.Text(Core.Safe(other,Core.Folder+"/installed.json"),Core.Json.Serialize(new State{root=other,mouse=true}));Fails(()=>Core.SetFrameGeneration(other,true),"another game root cannot take configuration lease");Core.RestoreFrameGeneration(root);
  root=New("uninstall");Core.SetFrameGeneration(root,true);Core.Uninstall(root);Check(!File.Exists(Engine)&&Core.ReadState(root)==null,"uninstall restores FG and removes lease");
  root=New("removed_created");Core.SetFrameGeneration(root,true);File.SetAttributes(Engine,FileAttributes.Normal);File.Delete(Engine);Check(Core.FrameGenerationRequested(root)==true,"missing pack-created file retains chosen request");Core.SetFrameGeneration(root,false);Check(File.Exists(Engine)&&(File.GetAttributes(Engine)&FileAttributes.ReadOnly)!=0&&Core.FrameGenerationRequested(root)==false,"missing pack-created file is recreated with protection on explicit save");File.SetAttributes(Engine,FileAttributes.Normal);File.Delete(Engine);Core.RestoreFrameGeneration(root);Check(!File.Exists(Engine)&&Core.ReadState(root).frameGeneration==null,"missing pack-created file safely restores original absence");
  root=New("removed_existing",Encoding.UTF8.GetBytes("[User]\nkey=7\n"));Core.SetFrameGeneration(root,true);File.SetAttributes(Engine,FileAttributes.Normal);File.Delete(Engine);Fails(()=>Core.SetFrameGeneration(root,false),"missing pre-existing configuration fails closed on save");Fails(()=>Core.RestoreFrameGeneration(root),"missing pre-existing configuration fails closed on restore");Fails(()=>Core.Suspend(root,true),"missing pre-existing configuration fails closed on suspend");
  root=New("removed_ambiguous");Core.SetFrameGeneration(root,true);var malformed=Core.ReadState(root);malformed.frameGeneration.previousSection="User";Core.Text(Core.Safe(root,Core.Folder+"/installed.json"),Core.Json.Serialize(malformed));File.SetAttributes(Engine,FileAttributes.Normal);File.Delete(Engine);Fails(()=>Core.RestoreFrameGeneration(root),"missing file recovery refuses nonempty original-section lease");
  root=New("removed_update");GameFixture(root);using(var payload=Payload())Core.Install(root,false,true,false,payload,"absent_installer");Core.SetFrameGeneration(root,true);File.SetAttributes(Engine,FileAttributes.Normal);File.Delete(Engine);using(var payload=Payload())Core.UpdatePreservingState(root,payload,"absent_installer");Check(Core.FrameGenerationRequested(root)==true&&Core.ReadState(root).mouse,"pack-created missing Engine does not block update or lose intent");Core.SetFrameGeneration(root,true);Check(File.Exists(Engine)&&(File.GetAttributes(Engine)&FileAttributes.ReadOnly)!=0,"post-update explicit save recreates protected file");Core.Uninstall(root);Check(!File.Exists(Engine),"post-recovery uninstall restores original absence");
  root=New("parked_uninstall",Encode("[User]\nkey=7\n","utf8"));Core.SetFrameGeneration(root,true);Core.Suspend(root,true);Core.Uninstall(root);Check(File.ReadAllText(Engine)=="[User]\nkey=7\n"&&Core.ReadState(root)==null,"suspended uninstall preserves original settings");
  root=New("update",Encode("[User]\nkey=7\n","utf8"));GameFixture(root);using(var payload=Payload())Core.Install(root,false,true,true,payload,"absent_installer");Core.SetFrameGeneration(root,true);byte[] active=File.ReadAllBytes(Engine);Core.WriteIni(Core.Config(root,"config.ini"),"control",new Dictionary<string,string>{{"sensitivity","0.087"}});
  using(var payload=Payload())Core.UpdatePreservingState(root,payload,"absent_installer");var updated=Core.ReadState(root);Check(updated.mouse&&updated.display&&!updated.campaign&&!updated.suspended&&updated.frameGeneration.enabled&&File.ReadAllBytes(Engine).SequenceEqual(active),"active update preserves FG lease and selected modules");Check(Core.ReadIni(Core.Config(root,"config.ini"),"control")["sensitivity"]=="0.087","active update preserves user control setting");
  Core.Suspend(root,true);byte[] suspended=File.ReadAllBytes(Engine);using(var payload=Payload())Core.UpdatePreservingState(root,payload,"absent_installer");updated=Core.ReadState(root);Check(updated.suspended&&updated.frameGeneration.enabled&&!updated.frameGeneration.live&&File.ReadAllBytes(Engine).SequenceEqual(suspended),"suspended update preserves FG selection and original configuration");Check(updated.mouse&&updated.display&&!updated.campaign&&Core.ReadIni(Core.Config(root,"config.ini"),"control")["sensitivity"]=="0.087","suspended update preserves modules and user controls");Core.Suspend(root,false);Core.Uninstall(root);Check(File.ReadAllText(Engine)=="[User]\nkey=7\n"&&Core.ReadState(root)==null,"updated uninstall removes ownership without residual override");
  root=New("status");string status=Core.Config(root,"upscaler_status.ini");long now=(long)(DateTime.UtcNow-new DateTime(1970,1,1)).TotalSeconds;
  Core.Text(status,"[upscaler_status]\nschema=1\nsample_unix="+now+"\ndlss_enabled=1\nfg_mode=2x\nfg_actual_frames=1\nfg_frame_rate=119.5\nfg_active=unknown\ntiming_source=native_last_present\n");var report=Core.ReadUpscalerStatus(root);Check(report["fg_actual_frames"]=="1"&&report["fg_active"]=="unknown","native enable and one-frame sample never promoted to active");Core.Text(status,File.ReadAllText(status).Replace(now.ToString(),(now-60).ToString()));Check(Core.ReadUpscalerStatus(root).Count==0,"stale status suppressed");
 }
 static void UiCases(){
  string root=New("ui");File.WriteAllText(Path.Combine(Core.FrameGenerationTestDirectory,"GameUserSettings.ini"),"[ConsoleVariables]\nr.Streamline.DLSSG.Enable=1\n");
  Application.EnableVisualStyles();
  foreach(float scale in new[]{1f,1.5f})using(var form=new Launcher(root)){
   form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-32000,-32000);form.AutoScaleMode=AutoScaleMode.None;if(scale!=1)form.Scale(new SizeF(scale,scale));form.ClientSize=new Size((int)(920*scale),(int)(760*scale));
   form.GetType().GetField("CheckUpdatesOnOpen").SetValue(form,false);form.Dialog=(text,icon)=>{throw new Exception(text);};form.Show();Application.DoEvents();
   var tabs=(TabControl)Find(form,"settingsTabs");tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(p=>p.Name=="Frame generation");var choice=(ComboBox)Find(form,"frameGenerationChoice");Check(choice.SelectedIndex==0,"UI inherits existing FG on request "+scale);
   foreach(string lang in new[]{"en","ko"}){
    ((ComboBox)Find(form,"uiLanguage")).SelectedIndex=lang=="ko"?1:0;Application.DoEvents();Button save=(Button)Find(form,"saveFrameGeneration"),restore=(Button)Find(form,"restoreFrameGeneration");
    Check(save.Text==(lang=="ko"?"프레임 생성 저장":"Save frame generation"),lang+" FG save label "+scale);Check(choice.Items.Count==2&&choice.Items[0].ToString()==(lang=="ko"?"켜기":"On"),lang+" FG-only choice "+scale);
    Check(save.Visible&&choice.Visible&&save.Bounds.Width>=160&&choice.Bounds.Height>=20,lang+" FG controls reachable "+scale);Capture(form,"fg_"+lang+"_"+(scale==1?"100":"150"));
    choice.SelectedIndex=1;save.PerformClick();Application.DoEvents();Check(Core.FrameGenerationRequested(root)==false,lang+" UI save uses real Core "+scale);restore.PerformClick();Application.DoEvents();Check(!File.Exists(Engine)&&Core.FrameGenerationRequested(root)==true,lang+" UI restore preserves manual request "+scale);
   }
   tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(p=>p.Name=="Play");((Button)Find(form,"standardPlay")).PerformClick();Application.DoEvents();tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(p=>p.Name=="Frame generation");Check(!Find(form,"saveFrameGeneration").Enabled,"suspended UI cannot save FG "+scale);tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(p=>p.Name=="Play");((Button)Find(form,"standardPlay")).PerformClick();Application.DoEvents();tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(p=>p.Name=="Frame generation");Check(Find(form,"saveFrameGeneration").Enabled,"resumed UI can save FG "+scale);
  }
 }
 public static int Run(string[] args){destination=Path.GetFullPath(args[0]);fixture=Path.Combine(destination,"fixtures");Directory.CreateDirectory(fixture);try{CoreCases();UiCases();File.WriteAllText(Path.Combine(destination,"results.json"),Core.Json.Serialize(new{passed=true,checks=checks.Count,results=checks}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(destination,"results.json"),Core.Json.Serialize(new{passed=false,checks=checks.Count,error=ex.ToString(),results=checks}));return 1;}}
}
